static int intent_hold,poisoned_route;static unsigned resets,local_steps;static int inject_refresh,task_active=1;static lab_status injected_poll_error;
static lab_status controlled_poll(void*u,uint64_t now,lab_live_sample*e){if(injected_poll_error){lab_status r=injected_poll_error;injected_poll_error=LAB_OK;return r;}return poll(u,now,e);}
static lab_status clean_reset(void*u,const lab_real_context*c){fixture*f=u;resets++;f->context=*c;f->loc.context=*c;f->loc.map.context=*c;f->loc.has_pose=0;f->loc.pose_time_us=0;f->loc.quality=0;f->loc.map.map_id=1000+c->origin_epoch;f->at=f->count=0;return LAB_OK;}
static const lab_live_source_ops clean_source={LAB_REAL_API_VERSION,sizeof(lab_live_source_ops),controlled_poll,health,clean_reset,close_fixture};
static const lab_localization_ops clean_loc={LAB_REAL_API_VERSION,sizeof(lab_localization_ops),push,snapshot,pose_at,set_map,initial,clean_reset,close_fixture};
static const lab_chassis_ops clean_chassis={LAB_REAL_API_VERSION,sizeof(lab_chassis_ops),feedback,protect,enable,apply,stop,clean_reset,close_fixture};
static void restart_event(fixture*f,uint64_t now){f->at=0;f->count=1;lab_live_sample*e=f->events;memset(e,0,sizeof(*e));e->type=LAB_EVENT_RESET;e->meta=(lab_real_meta){.context=f->context,.provider=3,.stream_id=205,.stream_session=201,.sequence=9,.flags=3,.time_us=now,.received_us=now,.parameter_version=1};e->data.reset.reason=LAB_RESET_SOURCE_CHANGE;e->data.reset.next_origin_epoch=f->context.origin_epoch+1;}
static int object_intent(void*u,const lab_real_runtime_view*v,uint64_t now,lab_real_command*out){(void)u;*out=(lab_real_command){.context=v->context,.generated_us=now,.expires_us=now+CONT_COMMAND_US,.linear_m_s=intent_hold?0:.08};return task_active;}
static lab_status local_step(void*u,uint64_t now,const lab_pose*p,uint64_t stamp,const lab_live_sample*s,const lab_real_command*desired,double cap,lab_real_command*out){(void)p;(void)stamp;(void)s;(void)cap;local_steps++;*out=*desired;if(poisoned_route)out->linear_m_s=.2;if(inject_refresh){inject_refresh=0;restart_event(u,now);}return LAB_OK;}
static lab_status local_publish(void*u,uint64_t now,const lab_pose*p,uint64_t stamp,lab_real_command*out){(void)u;(void)p;(void)stamp;CHECK(out->generated_us<=now&&out->expires_us>now);return LAB_OK;}
static lab_status local_mode(void*u,uint32_t mode){(void)u;(void)mode;return LAB_OK;}
static lab_real_runtime*create(fixture*f,unsigned mode,int hardware){lab_real_runtime_config c;lab_real_runtime_config_default(&c);c.mode=mode;c.allow_hardware_output=hardware;c.max_pose_age_us=CONT_ODOM_US;c.max_scan_age_us=CONT_SCAN_US;
 lab_real_bindings b={.sensors={f,&clean_source},.localization={f,&clean_loc},.chassis={f,&clean_chassis},.navigation={.user=f,.goal=goal,.cancel=cancel,.step=navstep,.reset=clean_reset,.local_step=local_step,.local_publish=local_publish,.local_mode=local_mode}};lab_real_runtime*r=NULL;CHECK(lab_real_runtime_open(&r,&c,&f->context,&b)==LAB_OK);CHECK(lab_real_runtime_object_controller(r,object_intent,f)==LAB_OK);return r;}
static lab_status tick(lab_real_runtime*r,uint64_t now){wall_us=now;return lab_real_runtime_tick(r,now);}
static void normal_reset_cancel(void){fixture f;init(&f,0);events(&f,1000000,1);lab_real_runtime*r=create(&f,LAB_REAL_SHADOW,0);CHECK(tick(r,1000000)==LAB_AGAIN);set_goal(r,1000000);CHECK(tick(r,1001000)==LAB_OK);unsigned applies=f.apply;restart_event(&f,1002000);CHECK(tick(r,1002000)==LAB_AGAIN);CHECK(view(r).context.origin_epoch==2&&!r->context_fault&&!r->clock_fault);CHECK(!view(r).has_odometry&&!view(r).has_scan&&!view(r).enabled&&!view(r).request.linear_m_s&&f.apply==applies);CHECK(r->recovery_goal_pending);CHECK(tick(r,1003000)==LAB_AGAIN);CHECK(!view(r).has_goal&&r->recovery_goal_pending);CHECK(lab_real_runtime_cancel(r,1003000)==LAB_OK&&!r->recovery_goal_pending);events(&f,1004000,1);CHECK(tick(r,1004000)==LAB_AGAIN);CHECK(!view(r).has_goal&&!view(r).enabled&&f.apply==applies);lab_real_runtime_close(r);free(f.events);puts("PASS source RESET main-poll rebuilds once, no old pose/command, cancel clears retained goal before new data");}
static void object_resets(int during_refresh){fixture f;init(&f,1);events(&f,2000000,1);lab_real_runtime*r=create(&f,LAB_REAL_NAVIGATION,1);CHECK(tick(r,2000000)==LAB_AGAIN);CHECK(lab_real_runtime_object_mode(r,2,2000001)==LAB_OK);events(&f,2001000,2);CHECK(tick(r,2001000)==LAB_AGAIN);CHECK(lab_real_runtime_enable(r,1,2001000)==LAB_OK);events(&f,2002000,3);CHECK(tick(r,2002000)==LAB_OK&&f.apply==1);unsigned before=f.apply,old_resets=resets;
 if(during_refresh){events(&f,2003000,4);inject_refresh=1;}else restart_event(&f,2003000);
 CHECK(tick(r,2003000)==LAB_AGAIN);CHECK(view(r).context.origin_epoch==2&&!r->context_fault&&!r->clock_fault);CHECK(view(r).object_mode==2&&view(r).object_soft_rearm_pending);CHECK(!view(r).has_scan&&!view(r).has_odometry&&!view(r).enabled&&!view(r).request.linear_m_s&&f.apply==before&&resets==old_resets+4);
 CHECK(tick(r,2004000)==LAB_AGAIN&&view(r).context.origin_epoch==2&&view(r).object_soft_rearm_pending&&f.apply==before);
 events(&f,2005000,1);CHECK(tick(r,2005000)==LAB_AGAIN);CHECK(view(r).object_soft_rearm_pending);CHECK(lab_real_runtime_object_rearm_ready(r,2005000)==LAB_OK);CHECK(lab_real_runtime_enable(r,1,2005000)==LAB_OK);events(&f,2006000,2);CHECK(tick(r,2006000)==LAB_OK&&f.apply==before+1);
 task_active=0;CHECK(lab_real_runtime_cancel(r,2007000)==LAB_OK);events(&f,2008000,3);CHECK(tick(r,2008000)==LAB_OK&&!view(r).enabled&&f.apply==before+1&&!view(r).object_soft_rearm_pending);task_active=1;lab_real_runtime_close(r);free(f.events);printf("PASS object RESET branch=%s retains active intent, no old publication, waits genuine data, explicit rearm recomputes, cancel never revives\n",during_refresh?"POSIX_PUBLICATION_REFRESH":"MAIN_POLL");}
static void fresh_weak_and_stale(void){fixture f;init(&f,0);events(&f,3000000,1);lab_real_runtime*r=create(&f,LAB_REAL_SHADOW,0);CHECK(tick(r,3000000)==LAB_AGAIN);set_goal(r,3000000);f.loc.state=LAB_REAL_LOC_DEGRADED;f.loc.odometry_fallback=1;strcpy(f.loc.reason,"WEAK_MATCH_ODOMETRY_CONTINUE");CHECK(tick(r,3600000)==LAB_OK&&view(r).request.linear_m_s>.0);CHECK(tick(r,4100001)==LAB_AGAIN&&!view(r).request.linear_m_s);events(&f,4101000,2);CHECK(tick(r,4101000)==LAB_OK&&view(r).request.linear_m_s>.0);lab_real_runtime_close(r);free(f.events);puts("PASS fresh degraded odometry accepted at600ms; genuinely aged source beyond1000ms blocks; new real events resume");}
static void revoked_reset(void){fixture f;init(&f,1);events(&f,5000000,1);lab_real_runtime*r=create(&f,LAB_REAL_NAVIGATION,1);CHECK(tick(r,5000000)==LAB_AGAIN);CHECK(lab_real_runtime_object_mode(r,2,5000001)==LAB_OK);r->view.manual_revoked=1;r->view.resume_requires_start=1;restart_event(&f,5001000);CHECK(tick(r,5001000)==LAB_AGAIN);CHECK(view(r).manual_revoked&&view(r).resume_requires_start&&!view(r).object_soft_rearm_pending&&!view(r).enabled);events(&f,5002000,1);CHECK(tick(r,5002000)==LAB_AGAIN);CHECK(lab_real_runtime_object_rearm_ready(r,5002000)!=LAB_OK&&!f.apply);lab_real_runtime_close(r);free(f.events);puts("PASS sensor RESET cannot erase explicit manual revoke or final-fault restart requirement");}
static void bad_sample_then_real_loss(void){fixture f;init(&f,1);events(&f,7000000,1);lab_real_runtime*r=create(&f,LAB_REAL_NAVIGATION,1);CHECK(tick(r,7000000)==LAB_AGAIN);CHECK(lab_real_runtime_object_mode(r,2,7000001)==LAB_OK);events(&f,7001000,2);CHECK(tick(r,7001000)==LAB_AGAIN);CHECK(lab_real_runtime_enable(r,1,7001000)==LAB_OK);events(&f,7002000,3);CHECK(tick(r,7002000)==LAB_OK&&f.apply==1);
 injected_poll_error=LAB_ERR_CRC;CHECK(tick(r,7003000)==LAB_OK&&f.apply==2);CHECK(view(r).scan_time_us==7002000&&view(r).odometry_time_us==7002000);
 events(&f,7004000,4);f.events[0].meta.flags=LAB_REAL_TIME_VALID;f.events[1].meta.flags=LAB_REAL_TIME_VALID;f.events[1].data.odometry.quality=LAB_POSE_STALE;CHECK(tick(r,7004000)==LAB_OK&&f.apply==3);CHECK(view(r).scan_time_us==7002000&&view(r).odometry_time_us==7002000&&view(r).rejected>=3);
 CHECK(tick(r,7002000+OBJECT_CONTROL_POSE_US+1001)==LAB_AGAIN&&f.apply==3&&!view(r).enabled);CHECK(view(r).odometry_time_us==7002000&&view(r).object_soft_rearm_pending);events(&f,7002000+OBJECT_CONTROL_POSE_US+2000,5);CHECK(tick(r,7002000+OBJECT_CONTROL_POSE_US+2000)==LAB_AGAIN);CHECK(lab_real_runtime_object_rearm_ready(r,7002000+OBJECT_CONTROL_POSE_US+2000)==LAB_OK);CHECK(lab_real_runtime_enable(r,1,7002000+OBJECT_CONTROL_POSE_US+2000)==LAB_OK);events(&f,7002000+OBJECT_CONTROL_POSE_US+3000,6);CHECK(tick(r,7002000+OBJECT_CONTROL_POSE_US+3000)==LAB_OK&&f.apply==4);lab_real_runtime_close(r);free(f.events);puts("PASS CRC and single invalid DATA_VALID/STALE samples do not refresh clocks or stop good continuity; sustained genuine loss stops; real new samples permit recomputed rearm");}
static void normal_uncalibrated_arm(void){fixture f;init(&f,1);events(&f,9000000,1);f.events[1].data.odometry.calibrated=0;f.events[1].data.odometry.quality=LAB_POSE_VALID|LAB_POSE_UNCALIBRATED|LAB_POSE_IMU_USED;lab_real_runtime*r=create(&f,LAB_REAL_NAVIGATION,1);CHECK(tick(r,9000000)==LAB_AGAIN);set_goal(r,9000000);CHECK(tick(r,9001000)==LAB_AGAIN);CHECK(!view(r).localization.pose.calibrated);CHECK(lab_real_runtime_start_ready(r,9001000)==LAB_OK);CHECK(lab_real_runtime_enable(r,1,9001000)==LAB_OK);CHECK(tick(r,9002000)==LAB_OK&&f.apply==1);CHECK(!view(r).localization.pose.calibrated&&(view(r).localization.pose.quality&LAB_POSE_UNCALIBRATED));lab_real_runtime_cancel(r,9003000);lab_real_runtime_close(r);free(f.events);puts("PASS normal valid uncalibrated estimate can ARM without falsifying calibrated=0 or quality flags");}
static void relative_goal_reprojection(void){fixture f;init(&f,0);events(&f,10000000,1);f.events[1].data.odometry.x_m=1;f.events[1].data.odometry.y_m=2;f.events[1].data.odometry.yaw_rad=1.5707963267948966;lab_real_runtime*r=create(&f,LAB_REAL_SHADOW,0);CHECK(tick(r,10000000)==LAB_AGAIN);lab_real_goal g={.map_id=99,.id=7,.x_m=3,.y_m=2};CHECK(lab_real_runtime_set_goal(r,&g,10000000)==LAB_OK);CHECK(tick(r,10001000)==LAB_OK);restart_event(&f,10002000);CHECK(tick(r,10002000)==LAB_AGAIN&&r->recovery_goal_pending);CHECK(!view(r).has_goal&&!view(r).has_localization);events(&f,10003000,1);CHECK(tick(r,10003000)==LAB_OK);CHECK(view(r).has_goal&&!r->recovery_goal_pending&&view(r).goal.map_id==1002);CHECK(fabs(view(r).goal.x_m)<1e-8&&fabs(view(r).goal.y_m+2)<1e-8);CHECK(view(r).request.context.origin_epoch==2&&view(r).request.generated_us==10003000);lab_real_runtime_close(r);free(f.events);puts("PASS retained goal is relative-estimate reprojected only after genuine new pose/map; command is recomputed in new epoch");}
static void authoritative_controller_hold(void){fixture f;init(&f,1);events(&f,11000000,1);lab_real_runtime*r=create(&f,LAB_REAL_NAVIGATION,1);CHECK(tick(r,11000000)==LAB_AGAIN);CHECK(lab_real_runtime_object_mode(r,1,11000001)==LAB_OK);events(&f,11001000,2);CHECK(tick(r,11001000)==LAB_AGAIN);CHECK(lab_real_runtime_enable(r,1,11001000)==LAB_OK);events(&f,11002000,3);CHECK(tick(r,11002000)==LAB_OK&&view(r).protected_output.command.linear_m_s>0);
 unsigned before=local_steps;intent_hold=1;poisoned_route=1;
 for(unsigned i=0;i<5;i++){events(&f,11003000+i*1000,4+i);CHECK(tick(r,11003000+i*1000)==LAB_OK);CHECK(view(r).request.linear_m_s==0&&view(r).request.angular_rad_s==0&&view(r).protected_output.command.linear_m_s==0);CHECK(local_steps==before);CHECK(!strcmp(view(r).navigation.reason,"OBJECT_CONTROLLER_HOLD_PRIORITY"));}
 intent_hold=poisoned_route=0;events(&f,11008000,9);CHECK(tick(r,11008000)==LAB_OK&&view(r).protected_output.command.linear_m_s>0&&local_steps==before+1);
 CHECK(lab_real_runtime_cancel(r,11009000)==LAB_OK);task_active=0;unsigned applied=f.apply;events(&f,11010000,10);CHECK(tick(r,11010000)==LAB_OK&&!view(r).enabled&&f.apply==applied);task_active=1;lab_real_runtime_close(r);free(f.events);puts("PASS zero controller/near intent bypasses malicious cached moving route, publishes zero immediately, fresh recompute may resume and explicit cancel cannot revive");}

int main(void){authoritative_controller_hold();normal_reset_cancel();object_resets(0);object_resets(1);fresh_weak_and_stale();revoked_reset();bad_sample_then_real_loss();normal_uncalibrated_arm();relative_goal_reprojection();printf("RELAX_RUNTIME_PASS assertions=%u local_steps=%u mock_hardware_only=1\n",checks,local_steps);return 0;}
